<section class="roster">
  <header class="roster__header">
    <h1 class="roster__title">Roster</h1>
  </header>

  <div class="roster__panel">
    <div class="roster__filters">
      <hlm-field class="roster__field roster__field--search">
        <label hlmFieldLabel for="roster-search">Search</label>
        <input
          hlmInput
          #search
          id="roster-search"
          type="search"
          placeholder="Name, alias or ID"
          (input)="vm.setQuery(search.value)"
        />
      </hlm-field>

      <hlm-field class="roster__field">
        <label hlmFieldLabel for="roster-class">Power class</label>
        <hlm-select
          [itemToString]="vm.classLabel"
          [value]="vm.classFilter()"
          (valueChange)="vm.setClassFilter($event)"
        >
          <hlm-select-trigger buttonId="roster-class" class="roster__select">
            <hlm-select-value />
          </hlm-select-trigger>
          <hlm-select-content *hlmSelectPortal>
            @for (option of vm.classOptions; track option) {
              <hlm-select-item [value]="option">{{ vm.classLabel(option) }}</hlm-select-item>
            }
          </hlm-select-content>
        </hlm-select>
      </hlm-field>

      <a hlmBtn routerLink="/recruit" class="roster__recruit">
        <ng-icon name="lucideUserPlus" />
        Recruit
      </a>
    </div>

    <div hlmTableContainer>
      <table hlmTable>
        <caption hlmTableCaption class="roster__caption">Heroes on the roster, strongest first</caption>
        <thead hlmTableHeader>
          <tr hlmTableRow>
            <th hlmTableHead scope="col">Hero</th>
            <th hlmTableHead scope="col">Class</th>
            <th hlmTableHead scope="col">Power</th>
            <th hlmTableHead scope="col">Status</th>
            <th hlmTableHead scope="col">Clearance</th>
            <th hlmTableHead scope="col">Actions</th>
          </tr>
        </thead>
        <tbody hlmTableBody>
          @for (row of vm.rows(); track row.hero.id) {
            <tr hlmTableRow>
              <td hlmTableCell>
                <div class="roster__identity">
                  <hlm-avatar class="roster__avatar">
                    <span hlmAvatarFallback>{{ row.initials }}</span>
                  </hlm-avatar>
                  <div class="roster__names">
                    <span class="roster__name">{{ row.hero.name }}</span>
                    <span class="roster__id">{{ row.hero.id }}</span>
                  </div>
                </div>
              </td>
              <td hlmTableCell>
                <span hlmBadge variant="outline">{{ row.hero.powerClass }}</span>
              </td>
              <td hlmTableCell>
                <span class="roster__power">{{ row.hero.powerIndex }}</span>
              </td>
              <td hlmTableCell>
                <span hlmBadge [variant]="row.statusTone">{{ row.hero.status }}</span>
              </td>
              <td hlmTableCell>{{ row.hero.clearance }}</td>
              <td hlmTableCell>
                <div class="roster__actions">
                  <a
                    hlmBtn
                    variant="ghost"
                    size="icon"
                    [routerLink]="['/detail', row.hero.id]"
                    [attr.aria-label]="'Edit ' + row.hero.name"
                    [hlmTooltip]="'Edit ' + row.hero.name"
                  >
                    <ng-icon name="lucidePencil" />
                  </a>
                </div>
              </td>
            </tr>
          } @empty {
            <tr hlmTableRow>
              <td hlmTableCell colspan="6">
                <p class="roster__empty">No heroes match these filters.</p>
              </td>
            </tr>
          }
        </tbody>
      </table>
    </div>

    <footer class="roster__footer">
      <p class="roster__count">{{ vm.summary() }}</p>
      <p class="roster__note">Sorted by power. Example data, not a real roster.</p>
    </footer>
  </div>
</section>

