                  [value]="vm.form.powerClass().value()"
                  (valueChange)="vm.setPowerClass($event)"
                >
                  <hlm-select-trigger buttonId="hero-class" class="hero-detail__select">
                    <hlm-select-value />
                  </hlm-select-trigger>
                  <hlm-select-content *hlmSelectPortal>
                    @for (option of vm.powerClasses; track option) {
                      <hlm-select-item [value]="option">{{ option }}</hlm-select-item>
                    }
                  </hlm-select-content>
                </hlm-select>
                @for (e of vm.form.powerClass().errors(); track e.kind) {
                  <hlm-field-error>{{ e.message }}</hlm-field-error>
                }
              </hlm-field>

              <hlm-field class="hero-detail__field">
                <label hlmFieldLabel for="hero-power">{{ vm.labels['powerIndex'].label }}</label>
                <input
                  hlmInput
                  id="hero-power"
                  type="number"
                  class="hero-detail__input"
                  [formField]="vm.form.powerIndex"
                />
                @for (e of vm.form.powerIndex().errors(); track e.kind) {
                  <hlm-field-error>{{ e.message }}</hlm-field-error>
                }
              </hlm-field>

              <div class="hero-detail__form-actions">
                @if (vm.notice()) {
                  <p class="hero-detail__notice" role="status">{{ vm.notice() }}</p>
                }
                <button hlmBtn variant="outline" type="button" (click)="vm.cancel()">Cancel</button>
                <button hlmBtn type="submit">Save</button>
              </div>
            </form>
          </div>
        </section>
      </div>
    </hlm-tabs>

    <hlm-dialog #retireDialog>
      <hlm-dialog-content *hlmDialogPortal>
        <hlm-dialog-header>
          <h2 hlmDialogTitle>Retire {{ hero.name }}?</h2>
          <p hlmDialogDescription>
            {{ hero.name }} will be taken off the roster. This cannot be undone from this console.
          </p>
        </hlm-dialog-header>
        <hlm-dialog-footer>
          <button hlmBtn variant="outline" type="button" (click)="retireDialog.close()">Cancel</button>
          <button
            hlmBtn
            variant="destructive"
            type="button"
            (click)="retireDialog.close(); vm.retire()"
          >
            Retire hero
          </button>
        </hlm-dialog-footer>
      </hlm-dialog-content>
    </hlm-dialog>
  } @else {
    <header class="hero-detail__header">
      <h1 class="hero-detail__title">No hero with that ID</h1>
    </header>
    <p class="hero-detail__note">The roster has no hero with this ID. It may have been retired.</p>
  }
</section>
==== forms/form-field-meta.ts
/**
 * Presentation metadata that rides on a zod field via `.meta()`. Strongly typed,
 * so a missing label is a compile error rather than a runtime surprise. A form
 * component reads this off the schema instead of restating labels and control
 * kinds in a parallel config object.
 */
export type ControlKind = 'text' | 'email' | 'number' | 'select' | 'checkbox' | 'textarea';

export interface FormFieldMeta {
  label: string;
  control: ControlKind;
  placeholder?: string;
  options?: ReadonlyArray<{ value: string; label: string }>;
  order?: number;
  help?: string;
}
==== forms/zod-meta.ts
import type { z } from 'zod';
import type { FormFieldMeta } from './form-field-meta';

/**
 * Read the FormFieldMeta off each field of a zod object schema. Keeps the label,
 * control kind, and placeholder on the schema (one source of truth) so a form
 * component reads them instead of restating them. Pair with `validateStandardSchema`
 * from `@angular/forms/signals` for validation, so shape, rules, and labels all
 * live on the one schema.
 */
export function formMeta(schema: z.ZodObject<z.ZodRawShape>): Record<string, FormFieldMeta> {
  const meta: Record<string, FormFieldMeta> = {};
  for (const [name, field] of Object.entries(schema.shape)) {
    meta[name] = (field as z.ZodType).meta() as unknown as FormFieldMeta;
  }
  return meta;
}

