        <hlm-field class="recruit__field">
          <label hlmFieldLabel for="recruit-power">{{ vm.labels['powerIndex'].label }}</label>
          <input
            hlmInput
            id="recruit-power"
            type="number"
            class="recruit__input"
            [formField]="vm.form.powerIndex"
          />
          @for (e of vm.form.powerIndex().errors(); track e.kind) {
            <hlm-field-error>{{ e.message }}</hlm-field-error>
          }
        </hlm-field>

        <div class="recruit__actions">
          <a hlmBtn variant="outline" routerLink="/roster">Cancel</a>
          <button hlmBtn type="submit">Recruit hero</button>
        </div>
